import pathlib,json
r=pathlib.Path('C:/lesiteinternetquitue/docs/encyclopedia-revision')
articles=[]
for p in sorted((r/'batches').glob('terpenes-*.json')):
 if p.stem[-2:] not in ['01','02','03','04','05']:continue
 d=json.loads(p.read_text(encoding='utf-8'))
 for a in d['articles']:
  articles.append(dict(id=a['id'],status='reviewed-no-blocking-pharmacology-error',findings=['Passages biologiques et assertions d’effet relus : les activités enzymatiques, détections et descriptions sensorielles ne sont pas présentées comme une efficacité thérapeutique. Les confirmations de présence et la chimie détaillée relèvent de la contrelecture du coordinateur.']))
out=dict(domain='terpenes',reviewerDomain='cannabinoids-pharmacology',reviewedAt='2026-11-14',scope='Contrelecture ciblée des passages biologiques/pharmacologiques des 35 fiches terpènes01–05, des sept articles pédagogiques et recherche des allégations de santé dans les quiz. Ce contrôle ne recertifie pas les 35 dossiers de présence botanique ni les images, revus séparément par le coordinateur.',overall='Aucune erreur pharmacologique bloquante repérée dans les textes actuels. Les limites humain/animal/cellule et odeur/effet sont correctement conservées. Cinq enrichissements précis proposés, avec sources primaires effectivement ouvertes.',articles=articles,sources=[],proposals=[],blockers=[],sensitivePoints=[])
def source(sid,title,url,author,org,published,access,passage,limitation=''):
 out['sources'].append(dict(id=sid,title=title,url=url,author=author,organization=org,published=published,verifiedAt='2026-11-14',access=access,passage=passage,documentKind='Publication originale',limitation=limitation,reviewEvidence=[dict(url=url,openedAt='2026-11-14',sections=passage,result='Passages réellement ouverts et lus.',supports=passage,access=access)]))
source('terpenes-lesson-spindle2024','Vaporized D-Limonene Selectively Mitigates the Acute Anxiogenic Effects of Δ9-Tetrahydrocannabinol in Healthy Adults Who Intermittently Use Cannabis','https://pmc.ncbi.nlm.nih.gov/articles/PMC11031290/','Tory R. Spindle et al.','Drug and Alcohol Dependence','2024','excerpt','Abstract ; Results 3.1–3.3 ; discussion des limites ; Funding et Conflicts of Interest.','URL PMID de PMC protégée par CAPTCHA ; identifiant PMC11031290 ouvert avec succès. Suppléments non lus. Résumé et résultats divergent sur la pharmacocinétique ; ne pas déclarer une absence universelle d’interaction PK.')
source('terpenes-lesson-kumar2025','Human study of α-pinene and Δ9-THC: cognitive effects','https://pmc.ncbi.nlm.nih.gov/articles/PMC12306963/','R. N. Kumar et al.','Medical Cannabis and Cannabinoids','2025','excerpt','Abstract ; Participants ; Cognitive Performance ; Adverse Effects ; Discussion et limites.','Les conclusions d’innocuité de l’auteur ne doivent pas devenir une garantie générale : petit effectif, exposition aiguë et deux retraits dans la condition combinée supérieure.')
source('rev-terpene-gertsch2008','Beta-caryophyllene is a dietary cannabinoid','https://www.for926.uni-bonn.de/kunden/for926/content/e229/e709/e1294/2008-Gertsch-PNAS.pdf','Jürg Gertsch et al.','PNAS','2008','excerpt','PDF p. 1–4 : résumé, résultats de liaison, signaux AMPc/calcium, effets dans le sang humain ex vivo et œdème chez les souris ; légende Fig. 5.','Copie de la publication originale ; résultats expérimentaux spécifiques. Aucune preuve clinique d’un cannabis riche en caryophyllène ; valeurs de Ki dépendantes de l’analyse et de la solubilité.')
source('cross-terpene-myrcene-vale2002','Central effects of citral, myrcene and limonene, constituents of essential oil chemotypes from Lippia alba','https://pubmed.ncbi.nlm.nih.gov/12587690/','T. Gurgel do Vale, E. Couto Furtado, J. G. Santos Jr et G. S. B. Viana','Phytomedicine','2002','abstract','Résumé : souris, administration intrapéritonéale, activité en champ ouvert, relaxation motrice et sommeil sous barbiturique.','Résumé seulement ; effectifs et données détaillées non visibles. La réduction de locomotion et la prolongation du sommeil sous pentobarbital ne sont pas une preuve de traitement de l’insomnie humaine.')
source('cross-terpene-finlay2020','Terpenoids From Cannabis Do Not Mediate an Entourage Effect by Acting at Cannabinoid Receptors','https://pmc.ncbi.nlm.nih.gov/articles/PMC7109307/','David B. Finlay et al.','Frontiers in Pharmacology','2020','excerpt','Introduction ; modèles HEK et CAMYEL ; résultats de liaison et AMPc, Fig. 1–4 ; discussion.','Concentrations, récepteurs surexprimés et voies mesurées limitent la généralisation. Petit effet de liaison CB2 du β-caryophyllène et d’un mélange, sans modulation AMPc détectée : ne pas écrire que tous les résultats sont nuls.')
source('cross-terpene-lavigne2021','Cannabis sativa terpenes are cannabimimetic and selectively enhance cannabinoid activity','https://pmc.ncbi.nlm.nih.gov/articles/PMC8050080/','Justin E. LaVigne, Ryan Hecksel, Attila Keresztes et John M. Streicher','Scientific Reports','2021','excerpt','Résultats comportementaux et Fig. 2–5 ; résultats CB1 in vitro et Fig. 6–8 ; discussion.','WIN55,212-2 est un cannabinoïde synthétique, pas le THC. Doses intrapéritonéales élevées chez la souris ; additivité ou synergie non résolue par la seule augmentation de réponse. Chaque voie cellulaire donne un résultat propre.')
source('terpenes-lesson-oxidation1992','Air oxidation of d-limonene creates potent allergens','https://onlinelibrary.wiley.com/doi/10.1111/j.1600-0536.1992.tb00129.x','Ann-Therése Karlberg, Kerstin Magnusson et Ulrika Nilsson','Contact Dermatitis','1992','abstract','Résumé : oxydation à l’air ; tests FCAT/GPMT chez le cobaye ; carvone et oxydes de limonène sensibilisants.','Ne pas généraliser une sensibilisation cutanée expérimentale à tout effet inhalatoire ni affirmer que toute molécule oxydée est toxique.')
source('terpenes-lesson-thermal2017','Toxicant Formation in Dabbing: The Terpene Story','https://pubmed.ncbi.nlm.nih.gov/28983528/','Jiries Meehan-Atrash, Wentai Luo et Robert M. Strongin','ACS Omega','2017','abstract','Résumé et légendes des figures : méthacroléine, benzène et autres produits ; limonène, linalol, myrcène ; répétitions et limites du modèle.','Résultats de chimie des émissions en laboratoire, pas un essai clinique ; aucune température universellement sûre ni risque individuel absolu n’en découle.')
out['proposals']=[
dict(articleIds=['ref-odeur-cannabis','record-terpene-limonene'],sectionIds=['ref-odeur-cannabis-pharmacologie','biology'],status='nonblocking-enrichment',finding='L’interprétation actuelle du signal Spindle est correcte. Préciser le dénominateur et le critère évite de lire « certains effets anxieux » comme une amélioration de toutes les échelles.',proposedParagraphAddition='Vingt adultes ont terminé les neuf conditions principales ; seuls douze ont effectué la condition supplémentaire, toujours en dernier. Dans cette dernière comparaison, deux évaluations visuelles, « anxieux/nerveux » et « paranoïaque », diminuent significativement ; la comparaison du score global STAI-S n’atteint pas le seuil annoncé (p = 0,08). Les performances cognitives ne sont pas protégées. Il s’agit de symptômes aigus ressentis après exposition expérimentale, sans démonstration de traitement d’un trouble anxieux.',sourceIds=['terpenes-lesson-spindle2024']),
dict(articleIds=['record-terpene-alphapinene'],sectionIds=['biology'],status='nonblocking-enrichment',finding='N = 19 et absence d’effet protecteur sont vérifiés. Le texte ne prétend pas à une innocuité absolue ; garder cette prudence si les paramètres sont enrichis.',proposedParagraphAddition='Les six séances comparent notamment 30 mg de THC avec 0,5, 5 ou 15 mg d’α-pinène, ainsi que les composés seuls et le placebo ; ces quantités décrivent le protocole, sans recommandation. Deux participants ont été retirés après des effets indésirables dans la combinaison contenant le plus d’α-pinène. Un résultat négatif chez 19 adultes ne prouve ni une absence de tout effet possible ni une sécurité chronique.',sourceIds=['terpenes-lesson-kumar2025']),
dict(articleIds=['record-terpene-myrcene'],sectionIds=['biology'],status='nonblocking-enrichment',finding='L’absence de déduction sédative depuis une teneur est juste. Pour expliquer le niveau préclinique plutôt que seulement le récuser, un exemple primaire est disponible.',proposedParagraphAddition='Chez la souris, une étude de 2002 observe une réduction de l’activité motrice et une prolongation du sommeil provoqué par un barbiturique après injection intrapéritonéale de myrcène. La voie, les quantités élevées, l’animal et l’association au barbiturique limitent la comparaison avec un arôme ou une fleur de cannabis. Ce modèle n’établit pas un traitement de l’insomnie chez l’humain.',sourceIds=['cross-terpene-myrcene-vale2002']),
dict(articleIds=['record-terpene-beta-caryophyllene','record-terpene-caryophyllene-oxide'],sectionIds=['biology'],status='nonblocking-enrichment',finding='Le β-caryophyllène agoniste CB2 dans Gertsch est correctement attribué. L’oxyde et l’humulène ne partagent pas automatiquement cette interaction ; les résultats de Finlay limitent une généralisation mécanistique.',proposedParagraphAddition='Gertsch distingue le (E)-β-caryophyllène de son oxyde et de l’humulène : ces deux derniers ne déplacent pas le radioligand CB2 dans le test rapporté. L’effet anti-inflammatoire chez des souris normales, comparées à des souris dépourvues de CB2, soutient une implication du récepteur dans ce modèle. Une autre étude cellulaire, Finlay 2020, détecte seulement un faible déplacement de liaison par le β-caryophyllène et aucune activation AMPc significative dans ses conditions. Le mécanisme doit donc toujours être lié au système expérimental ; il ne constitue pas une preuve d’efficacité clinique.',sourceIds=['rev-terpene-gertsch2008','cross-terpene-finlay2020']),
dict(articleIds=['ref-odeur-cannabis','record-terpene-linalool','record-terpene-betapinene','record-terpene-alpha-humulene'],sectionIds=['ref-odeur-cannabis-pharmacologie','biology'],status='nonblocking-enrichment',finding='Les textes actuels n’affirment pas une synergie clinique. Une comparaison explicitement expérimentale pourrait enrichir le dossier sans adopter un slogan universel pour ou contre l’entourage.',proposedParagraphAddition='Les expériences ne testent pas toutes la même interaction. Finlay étudie des récepteurs humains exprimés dans des cellules et ne détecte pas de modulation de la voie AMPc par les terpènes testés. LaVigne observe chez la souris des effets combinés de certains terpènes avec le cannabinoïde synthétique WIN55,212-2 ; ce résultat ne démontre pas une synergie avec le THC chez l’humain. L’étude elle-même distingue une réponse augmentée d’une synergie qui resterait à caractériser. Les essais humains limonène et α-pinène évaluent encore d’autres critères : anxiété ressentie et mémoire.',sourceIds=['cross-terpene-finlay2020','cross-terpene-lavigne2021','terpenes-lesson-spindle2024','terpenes-lesson-kumar2025'])]
out['sensitivePoints']=[
'Spindle : 38 participants randomisés, 20 analysés après complétion, 12 dans la condition supérieure non randomisée. Ne pas appeler ce sous-groupe un bras parallèle randomisé. Brevet déclaré après l’étude et soutien matériel mentionnés ; ce conflit ne réfute pas automatiquement les données.',
'Spindle : le résumé annonce une absence d’effet PK, mais Results 3.6 rapporte une Cmax THC plus forte dans la combinaison supérieure. Les notices actuelles n’abordent pas ce point ; ne pas ajouter une assertion globale sans expliciter cette différence.',
'Kumar : α-pinène, pas β-pinène ; aucune protection cognitive dans ce protocole. Deux retraits liés aux événements indésirables dans la condition combinée supérieure ne prouvent pas que le terpène seul en est la cause.',
'CB2/Gertsch : cellules humaines ex vivo ne signifie pas essai clinique humain. Au moins neuf souris par groupe dans la Fig. 5, doses expérimentales 5 et 10 mg/kg ; effets hors cible évoqués à dose supérieure. Aucune conversion de ces quantités en usage humain.',
'Finlay/LaVigne : cibles, voies, concentrations et comparateurs différents ; ne pas résoudre leurs différences par une affirmation universelle d’existence ou d’inexistence d’entourage.',
'Oxydation : sensibilisation cutanée chez le cobaye, distincte du risque des émissions chauffées. Chauffage : méthacroléine et benzène détectés, sans seuil universel de sécurité. Les formulations actuelles conservent ces limites.',
'Aucun quiz pharmacologique affirmatif problématique trouvé dans les 35 fiches : les questions associées portent essentiellement sur arômes, structures et biosynthèse.']
assert len(articles)==35
(r/'cross-reviews/terpenes-pharmacology.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print('Contrelecture ciblée : 35 fiches, 8 sources ouvertes, 5 enrichissements non bloquants.')
